script:
frappe.ui.form.on('Job Order', {
  refresh(frm) {
    const reviewers = ['chandy@saifaudit.com','santhosh@saifaudit.com','Administrator'];
    const can = reviewers.includes(frappe.session.user);
    ['custom_reviewer_rating','custom_review_remark'].forEach(f => frm.set_df_property(f,'read_only', can?0:1));
    if (!can) frm.set_df_property('custom_reviewer_rating','description','Only the reviewer (Chandy/Santhosh) can set this.');
  }
});
